#include "game/LawSystem.h"
#include <algorithm>
int LawSystem::fineFor(TrafficOffense o){switch(o){case TrafficOffense::Speeding:return 250;case TrafficOffense::RedLight:return 350;case TrafficOffense::WrongWay:return 500;case TrafficOffense::RecklessDriving:return 750;case TrafficOffense::HitAndRun:return 1800;case TrafficOffense::EvadingStop:return 2500;default:return 0;}}
void LawSystem::report(TrafficOffense o,bool witnessed,WantedSystem&w){if(!witnessed||o==TrafficOffense::None)return;policeWitness=true;lastCitation={o,fineFor(o)};if(o==TrafficOffense::HitAndRun){state=PoliceState::Pursuit;w.addHeat(24);}else if(state==PoliceState::Patrol){state=PoliceState::StopRequested;stateTimer=12;w.addHeat(5);}}
void LawSystem::obeyStop(WantedSystem&w){if(state!=PoliceState::StopRequested)return;state=PoliceState::Citation;totalFines+=lastCitation.fine;stateTimer=4;w.reduceHeat(12);}
void LawSystem::refuseStop(WantedSystem&w){if(state!=PoliceState::StopRequested)return;state=PoliceState::Pursuit;lastCitation={TrafficOffense::EvadingStop,fineFor(TrafficOffense::EvadingStop)};w.addHeat(22);}
void LawSystem::resolveCrash(float injury,WantedSystem&w){if(state!=PoliceState::Pursuit&&state!=PoliceState::StopRequested)return;if(injury>=0.70f){state=PoliceState::Ambulance;stateTimer=6;}else{state=PoliceState::Arrested;stateTimer=4;w.addHeat(5);}}
void LawSystem::update(float dt,WantedSystem&w){if(stateTimer>0)stateTimer-=dt;if(state==PoliceState::StopRequested&&stateTimer<=0)refuseStop(w);else if(state==PoliceState::Citation&&stateTimer<=0){state=PoliceState::Patrol;w.clear();}else if(state==PoliceState::Arrested&&stateTimer<=0){state=PoliceState::Jail;jailSeconds=60+w.level*45;w.clear();}else if(state==PoliceState::Ambulance&&stateTimer<=0){state=PoliceState::Hospital;stateTimer=8;}else if(state==PoliceState::Hospital&&stateTimer<=0){state=PoliceState::Jail;jailSeconds=45;w.clear();}}
